const menu=document.querySelector('.menu-toggle');const mobileNav=document.querySelector('.mobile-nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Fechar menu':'Abrir menu');mobileNav.classList.toggle('open',open)});mobileNav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Abrir menu');mobileNav.classList.remove('open')}));
const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.1});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));
document.querySelectorAll('.portfolio-row').forEach(row=>{const track=row.querySelector('.category-track'),cards=[...track.querySelectorAll('.category-card')];function move(direction){const x=track.getBoundingClientRect().left;const current=cards.reduce((best,card,i)=>Math.abs(card.getBoundingClientRect().left-x)<Math.abs(cards[best].getBoundingClientRect().left-x)?i:best,0);const next=Math.min(cards.length-1,Math.max(0,current+direction));track.scrollTo({left:cards[next].offsetLeft-cards[0].offsetLeft,behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'})}row.querySelector('.category-prev')?.addEventListener('click',()=>move(-1));row.querySelector('.category-next')?.addEventListener('click',()=>move(1));track.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();move(e.key==='ArrowRight'?1:-1)}})});
const names={casamento:'CASAMENTOS',formatura:'FORMATURAS',aniversario:'ANIVERSÁRIOS',evento:'EVENTOS'};const projects={};document.querySelectorAll('.portfolio-row').forEach(row=>{const cards=[...row.querySelectorAll('.category-card')];cards.forEach((card,index)=>{const images=[card,...cards.filter(c=>c!==card)].slice(0,3).map(c=>[c.querySelector('img').getAttribute('src'),c.querySelector('img').alt]);projects[card.dataset.gallery]=images})});projects['casamento-01']=[['assets/hero.jpg','Casal durante cerimônia ao pôr do sol'],...projects['casamento-01'].slice(1)];
const dialog=document.querySelector('#gallery-dialog'),dialogImage=dialog.querySelector('img');let activeGallery=[],photoIndex=0,returnFocus=null;function showPhoto(index){photoIndex=(index+activeGallery.length)%activeGallery.length;dialogImage.src=activeGallery[photoIndex][0];dialogImage.alt=activeGallery[photoIndex][1];dialog.querySelector('.dialog-count').textContent=`${String(photoIndex+1).padStart(2,'0')} / ${String(activeGallery.length).padStart(2,'0')}`}document.querySelectorAll('[data-gallery]').forEach(button=>button.addEventListener('click',()=>{activeGallery=projects[button.dataset.gallery];returnFocus=button;const cardTitle=button.querySelector('strong')?.textContent;const [type,num]=button.dataset.gallery.split('-');dialog.querySelector('.dialog-title').textContent=cardTitle?`${names[type] || 'GALERIA'} / ${cardTitle.toUpperCase()}`:`${names[type]} / HISTÓRIA ${num}`;showPhoto(0);dialog.showModal()}));dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.querySelector('.dialog-prev').addEventListener('click',()=>showPhoto(photoIndex-1));dialog.querySelector('.dialog-next').addEventListener('click',()=>showPhoto(photoIndex+1));dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});dialog.addEventListener('close',()=>{dialogImage.removeAttribute('src');returnFocus?.focus()});dialog.addEventListener('keydown',e=>{if(e.key==='ArrowRight')showPhoto(photoIndex+1);if(e.key==='ArrowLeft')showPhoto(photoIndex-1)});
document.querySelectorAll('[data-plan]').forEach(a=>a.addEventListener('click',()=>{document.querySelector('#contact-form').dataset.plan=a.dataset.plan}));const WHATSAPP_NUMBER='';document.querySelector('#contact-form').addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget,d=new FormData(form);const date=String(d.get('date')).split('-').reverse().join('/');const plan=form.dataset.plan?`\nPacote de interesse: ${form.dataset.plan}`:'';const message=`Olá! Meu nome é ${d.get('name')}. Gostaria de conversar sobre uma cobertura fotográfica.\n\nEvento: ${d.get('event')}\nData: ${date}\nCidade: ${d.get('city')}${plan}\nDetalhes: ${d.get('details')||'Gostaria de saber mais sobre as possibilidades.'}`;const url=WHATSAPP_NUMBER?`https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(message)}`:`https://api.whatsapp.com/send?text=${encodeURIComponent(message)}`;window.open(url,'_blank','noopener,noreferrer')});document.querySelector('#year').textContent=new Date().getFullYear();let ticking=false;window.addEventListener('scroll',()=>{if(ticking)return;ticking=true;requestAnimationFrame(()=>{const height=document.documentElement.scrollHeight-innerHeight;document.querySelector('.scroll-progress').style.width=(height>0?scrollY/height*100:0)+'%';ticking=false})},{passive:true});
